import { VoxelBoundsSelectionControls } from "./VoxelBoundsSelectionControls";
import { VoxelBoundsSelection } from "@divinevoxel/vlox/Templates/Selection/VoxelBoundsSelection";
import { Vector3Like } from "@amodx/math";
import { Axes } from "@amodx/math/Vectors/Axes";
import FlipTemplate from "@divinevoxel/vlox/Templates/Functions/FlipTemplate";
import RotateTemplate from "@divinevoxel/vlox/Templates/Functions/RotateTemplate";
import { VoxelTemplateMesh } from "./VoxelTemplateMesh";
export class VoxelTemplateControls {
    scene;
    space;
    ray;
    template;
    selection;
    selectionControls;
    mesh;
    constructor(scene, space, ray, template, selection = new VoxelBoundsSelection()) {
        this.scene = scene;
        this.space = space;
        this.ray = ray;
        this.template = template;
        this.selection = selection;
        this.selection.reConstruct(this.selection.bounds.min, Axes.UpReadOnly(), Vector3Like.Add(this.selection.bounds.min, template.bounds.size), Axes.UpReadOnly());
        this.selectionControls = new VoxelBoundsSelectionControls(scene, ray, this.selection, false);
        this.mesh = new VoxelTemplateMesh(scene);
        this.rebuildSelection();
    }
    rebuildSelection() {
        this.selection.reConstruct(Vector3Like.Add(this.template.bounds.min, this.selection.origin), Axes.UpReadOnly(), Vector3Like.Add(this.template.bounds.max, this.selection.origin), Axes.UpReadOnly());
        this.selectionControls.sync();
        this.mesh.update(this.template);
    }
    async place() {
        await this.space.paintTemplate(this.selection.origin, this.template.toJSON());
    }
    async clear() {
        await this.space.eraseTemplate(this.selection.origin, this.template.toJSON());
    }
    flip(axis) {
        FlipTemplate(this.template, axis);
        this.rebuildSelection();
    }
    rotate(axis, angle) {
        RotateTemplate(this.template, angle, axis);
        this.rebuildSelection();
    }
    update(selectionActive) {
        this.selectionControls.update(selectionActive);
        this.mesh.parent.position.set(this.selection.bounds.min.x, this.selection.bounds.min.y, this.selection.bounds.min.z);
    }
    dispose() {
        this.selectionControls.dispose();
        this.mesh.dispose();
    }
}
